private static final Map<String, String> SORT_COLUMNS = Map.of(
        "id", "id", "email", "email", "created", "created_at");   // whitelist cho phần không bind được

public List<UserRow> search(String keyword, String sortKey) throws SQLException {
    String orderBy = SORT_COLUMNS.getOrDefault(sortKey, "id");
    String sql = "SELECT id, email, role FROM users "
            + "WHERE role = 'CUSTOMER' AND email LIKE ? ESCAPE '\\' "
            + "ORDER BY " + orderBy;
    try (Connection conn = dataSource.getConnection();
         PreparedStatement ps = conn.prepareStatement(sql)) {
        ps.setString(1, "%" + escapeLike(keyword) + "%");          // giá trị đi qua tham số
        try (ResultSet rs = ps.executeQuery()) {
            return mapRows(rs);
        }
    }
}

private static String escapeLike(String s) {
    return s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
}
